import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{ name: string, params: any, trigger?: string }>} [cinematicPrimitives]
 * @property {any} [textContent]
 * @property {any} [intent]
 * @property {any} [colors]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{ loadTexture: (url:string)=>Promise<any> }} textureLoader
 * @property {{ emit: (event:string, payload?:any)=>void }} emit
 * @property {{ primitives: Record<string, (target:any, params:any)=>{ timeline:any, cleanup:()=>void }> }} primitives
 * @property {{ fontAtlas: { createText: (content:string, opts?:any)=>any } }} fontAtlas
 */

/**
 * Creates the Journal card 2 label node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  /** @type {THREE.Group} */
  const root = new Group();

  // ----------------------------
  // Plane (card background)
  // ----------------------------
  const aspect = 512 / 320; // image aspect
  const width = 1.6; // arbitrary scene units, keeps aspect ratio
  const height = width / aspect;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });

  const plane = new Mesh(geometry, material);
  // Slight offset to avoid z‑fighting with text
  plane.position.set(0, 0, 0.001);
  root.add(plane);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        material.map = tex;
        material.needsUpdate = true;
      })
      .catch(() => {
        // texture load failure – keep white material
      });
  }

  // ----------------------------
  // Text content
  // ----------------------------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // ----------------------------
  // Cinematic primitives
  // ----------------------------
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim && typeof prim.name === 'string') {
        const instance = ctx.primitives[prim.name](
          root,
          prim.params || {}
        );
        primitiveInstances.push(instance);
      }
    }
  }

  // ----------------------------
  // Interaction (hover & click)
  // ----------------------------
  let hoverTimeline = null;
  let baseY = 0;

  function onHoverEnter() {
    baseY = root.position.y;
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(root.position, {
      y: baseY + 0.15,
      duration: 0.3,
      ease: 'power3.out',
    });
  }

  function onHoverLeave() {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(root.position, {
      y: baseY,
      duration: 0.3,
      ease: 'power3.out',
    });
  }

  function onClick() {
    ctx.emit('hub-journal.select');
  }

  // expose handlers for external event system
  root.userData.handlers = {
    hover: {
      enter: onHoverEnter,
      leave: onHoverLeave,
    },
    click: onClick,
  };

  // ----------------------------
  // Cleanup
  // ----------------------------
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Kill hover animation
    if (hoverTimeline) hoverTimeline.kill();

    // Cleanup primitives
    for (const pi of primitiveInstances) {
      if (pi && typeof pi.cleanup === 'function') {
        pi.cleanup();
      }
    }
  };

  return root;
}
